	"net/http"
	"net/url"
	"strconv"
	"time"
)

const defaultAPIURL = "http://localhost:12111"

// ErrUnauthorized is returned when the API rejects the key.
var ErrUnauthorized = errors.New("API key rejected (401 unauthorized)")

type Customer struct {
	ID      string  `json:"id"`
	Object  string  `json:"object"`
	Email   *string `json:"email"`
	Name    *string `json:"name"`
	Created int64   `json:"created"`
}

type Subscription struct {
	ID       string `json:"id"`
	Object   string `json:"object"`
	Customer string `json:"customer"`
	Status   string `json:"status"`
	Created  int64  `json:"created"`
}

type Client struct {
	BaseURL    string
	APIKey     string
	HTTP       *http.Client
	MaxRetries int
	// Sleep waits between retries; overridable in tests.
	Sleep func(ctx context.Context, d time.Duration) error
}

func NewClient(baseURL, key string) *Client {
	return &Client{
		BaseURL:    baseURL,
		APIKey:     key,
		HTTP:       &http.Client{Timeout: 30 * time.Second},
		MaxRetries: 8,
		Sleep:      sleepCtx,
	}
}

func sleepCtx(ctx context.Context, d time.Duration) error {
	t := time.NewTimer(d)
	defer t.Stop()
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-t.C:
		return nil
	}
}

// get performs a GET, retrying on 429 (honouring Retry-After) and 5xx.
func (c *Client) get(ctx context.Context, path string, q url.Values, out any) error {
	u := c.BaseURL + path
	if len(q) > 0 {
		u += "?" + q.Encode()
	}
	for attempt := 0; ; attempt++ {
		req, err := http.NewRequestWithContext(ctx, http.MethodGet, u, nil)
		if err != nil {
			return err
		}
		req.Header.Set("Authorization", "Bearer "+c.APIKey)
		resp, err := c.HTTP.Do(req)
		var body []byte
		status := 0
		var retryAfter time.Duration
		if err == nil {
			status = resp.StatusCode
			body, err = io.ReadAll(resp.Body)
			resp.Body.Close()
			if s := resp.Header.Get("Retry-After"); s != "" {
				if n, perr := strconv.ParseFloat(s, 64); perr == nil && n >= 0 {
					retryAfter = time.Duration(n * float64(time.Second))
				}
			}
		}
		retryable := err != nil && ctx.Err() == nil || status == http.StatusTooManyRequests || status >= 500
		if retryable && attempt < c.MaxRetries {
			wait := retryAfter
			if wait == 0 {
				wait = min(time.Duration(1<<attempt)*250*time.Millisecond, 10*time.Second)
			}
			if serr := c.Sleep(ctx, wait); serr != nil {
				return serr
			}
			continue
		}
		if err != nil {
			return fmt.Errorf("GET %s: %w", path, err)
		}
		if status == http.StatusUnauthorized {
			return ErrUnauthorized
		}
		if status < 200 || status > 299 {
			return fmt.Errorf("GET %s: %s", path, apiError(status, body))
		}
		if err := json.Unmarshal(body, out); err != nil {
			return fmt.Errorf("GET %s: decoding response: %w", path, err)
		}
		return nil
	}
